customScripts.product_slider:
(function(root, ctx){
  if (!root) return;
  var initKey = 'mfInit_product_slider';
  if (root.dataset && root.dataset[initKey] === '1') return;
  if (root.dataset) root.dataset[initKey] = '1';

  var wrapper = root.querySelector('.product-slider-wrapper');
  if (!wrapper) return;

  var slider = wrapper.querySelector('.product-slider');
  var track = wrapper.querySelector('.product-slider-track');
  var cards = Array.prototype.slice.call(wrapper.querySelectorAll('.product-card'));
  var prevBtn = wrapper.querySelector('.slider-prev');
  var nextBtn = wrapper.querySelector('.slider-next');
  var dotsContainer = wrapper.querySelector('.slider-dots');

  if (!slider || !track || !cards.length) return;

  var currentIndex = 0;
  var timer = null;
  var touchStartX = 0;

  function visibleCards() {
    var w = window.innerWidth || 1280;
    if (w <= 480) return 1;
    if (w <= 640) return 2;
    return 3;
  }

  function maxIndex() {
    return Math.max(0, cards.length - visibleCards());
  }

  function cardStep() {
    if (!cards.length) return 0;
    var first = cards[0];
    var styles = window.getComputedStyle(track);
    var gap = parseFloat(styles.columnGap || styles.gap || '16') || 16;
    return first.getBoundingClientRect().width + gap;
  }

  function ensureDots() {
    if (!dotsContainer) return;
    var needed = maxIndex() + 1;
    var existing = dotsContainer.querySelectorAll('.dot');
    if (existing.length === needed) return;
    dotsContainer.innerHTML = '';
    for (var i = 0; i < needed; i++) {
      (function(index){
        var dot = document.createElement('button');
        dot.type = 'button';
        dot.className = 'dot' + (index === currentIndex ? ' active' : '');
        dot.setAttribute('aria-label', 'Go to product slide ' + (index + 1));
        dot.addEventListener('click', function(){ goTo(index, true); });
        dotsContainer.appendChild(dot);
      })(i);
    }
  }

  function updateDots() {
    if (!dotsContainer) return;
    var dots = dotsContainer.querySelectorAll('.dot');
    for (var i = 0; i < dots.length; i++) {
      dots[i].classList.toggle('active', i === currentIndex);
    }
  }

  function render() {
    var step = cardStep();
    if (!step) return;
    currentIndex = Math.max(0, Math.min(currentIndex, maxIndex()));
    track.style.transform = 'translateX(-' + (currentIndex * step) + 'px)';
    ensureDots();
    updateDots();
  }

  function goTo(index, restart) {
    currentIndex = Math.max(0, Math.min(index, maxIndex()));
    render();
    if (restart) startAuto();
  }

  function next(restart) {
    currentIndex = currentIndex >= maxIndex() ? 0 : currentIndex + 1;
    render();
    if (restart) startAuto();
  }

  function prev(restart) {
    currentIndex = currentIndex <= 0 ? maxIndex() : currentIndex - 1;
    render();
    if (restart) startAuto();
  }

  function stopAuto() {
    if (timer) {
      window.clearInterval(timer);
      timer = null;
    }
  }

  function startAuto() {
    stopAuto();
    timer = window.setInterval(function(){ next(false); }, 4000);
  }

  function onResize() {
    render();
  }

  function onPrevClick() { prev(true); }
  function onNextClick() { next(true); }
  function onMouseEnter() { stopAuto(); }
  function onMouseLeave() { startAuto(); }
  function onTouchStart(e) {
    if (!e.touches || !e.touches.length) return;
    touchStartX = e.touches[0].clientX;
    stopAuto();
  }
  function onTouchEnd(e) {
    if (!e.changedTouches || !e.changedTouches.length) return;
    var diff = touchStartX - e.changedTouches[0].clientX;
    if (Math.abs(diff) > 50) {
      if (diff > 0) next(false);
      else prev(false);
    }
    startAuto();
  }

  if (prevBtn) prevBtn.addEventListener('click', onPrevClick);
  if (nextBtn) nextBtn.addEventListener('click', onNextClick);
  wrapper.addEventListener('mouseenter', onMouseEnter);
  wrapper.addEventListener('mouseleave', onMouseLeave);
  track.addEventListener('touchstart', onTouchStart, { passive: true });
  track.addEventListener('touchend', onTouchEnd, { passive: true });
  window.addEventListener('resize', onResize);

  window.setTimeout(render, 0);
  window.setTimeout(render, 120);
  startAuto();

  if (ctx && typeof ctx.registerCleanup === 'function') {
    ctx.registerCleanup([
      function(){ stopAuto(); },
      function(){ if (prevBtn) prevBtn.removeEventListener('click', onPrevClick); },
      function(){ if (nextBtn) nextBtn.removeEventListener('click', onNextClick); },
      function(){ wrapper.removeEventListener('mouseenter', onMouseEnter); },
      function(){ wrapper.removeEventListener('mouseleave', onMouseLeave); },
      function(){ track.removeEventListener('touchstart', onTouchStart); },
      function(){ track.removeEventListener('touchend', onTouchEnd); },
      function(){ window.removeEventListener('resize', onResize); }
    ]);
  }
})(window.__mfCurrentScriptRoot, window.__mfScriptContext);

